/* Theme tokens: day is the default; night applies via data-theme or the OS dark preference. */
:root {
  --my-accent: #3d5c4b;
  --my-on-accent: #f7f5ef;
  --my-surface: #e9e7df;
  --my-ink: #1e2722;
