}

:root[data-theme="night"] {
  --my-accent: #8fb7a0;
  --my-on-accent: #111a15;
  --my-surface: #1b231f;
  --my-ink: #e4e9e5;
  --my-muted: #9aa69e;
  --my-line: #3a4640;
  --my-focus: #8ab4ff;
  --my-disabled-bg: #252e29;
  --my-disabled-ink: #5d6862;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="day"]) {
    --my-accent: #8fb7a0;
    --my-on-accent: #111a15;
    --my-surface: #1b231f;
    --my-ink: #e4e9e5;
    --my-muted: #9aa69e;
    --my-line: #3a4640;
    --my-focus: #8ab4ff;
    --my-disabled-bg: #252e29;
    --my-disabled-ink: #5d6862;
  }
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.75rem;
  font-family: inherit;
}

.button-row__btn {
  appearance: none;
  min-height: 44px;
  padding: 0.6rem 1.25rem;
  font: inherit;
  font-size: 0.95rem;
  line-height: 1.2;
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease;
}

.button-row__btn:focus-visible {
  outline: 2px solid var(--my-focus);
  outline-offset: 3px;
}

.button-row__btn:disabled {
  cursor: not-allowed;
}

/* Primary: solid accent fill, the one thing to do on this screen. */
.button-row__btn--primary {
  border: 1px solid var(--my-accent);
  background-color: var(--my-accent);
  color: var(--my-on-accent);
  font-weight: 600;
}

.button-row__btn--primary:hover:not(:disabled) {
  filter: brightness(1.08);
}

.button-row__btn--primary:disabled {
  border-color: var(--my-disabled-bg);
  background-color: var(--my-disabled-bg);
  color: var(--my-disabled-ink);
}

/* Secondary: outlined, supporting action. */
.button-row__btn--secondary {
  border: 1px solid var(--my-line);
  background-color: transparent;
  color: var(--my-ink);
  font-weight: 500;
}

.button-row__btn--secondary:hover:not(:disabled) {
  border-color: var(--my-accent);
  color: var(--my-accent);
}

.button-row__btn--secondary:disabled {
  border-color: var(--my-disabled-bg);
  color: var(--my-disabled-ink);
}

/* Quiet: text only, no chrome until interacted with. */
.button-row__btn--quiet {
  border: 1px solid transparent;
  padding-left: 0.75rem;
  padding-right: 0.75rem;
  background-color: transparent;
  color: var(--my-muted);
  font-weight: 500;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
}

.button-row__btn--quiet:hover:not(:disabled) {
  color: var(--my-ink);
  text-decoration-color: currentColor;
}

.button-row__btn--quiet:disabled {
  color: var(--my-disabled-ink);
  text-decoration-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  .button-row__btn {
    transition: none;
  }
}
